const items = $input.all();
const productos = new Map();

for (const item of items) {
  const fila = item.json;

  const numeroFila = fila.row_number ?? "DESCONOCIDA";
  const codigoOriginal = String(fila["Código"] ?? "").trim();

  const codigo = codigoOriginal ||
    `SIN_CODIGO_FILA_${numeroFila}`;

  const nombre = String(fila["Producto"] ?? "").trim();
  const tipo = String(fila["Tipo Concepto"] ?? "").trim();
  const unidad = String(fila["Medida"] ?? "").trim();
  const lote = String(fila["Lote"] ?? "").trim();

  const cantidadOriginal = fila["Cantidad"];

  const cantidad = Number(cantidadOriginal);

  const cantidadValida =
    cantidadOriginal !== "" &&
    cantidadOriginal !== null &&
    cantidadOriginal !== undefined &&
    Number.isFinite(cantidad) &&
    Number.isInteger(cantidad) &&
    cantidad >= 0;

  if (!productos.has(codigo)) {
    productos.set(codigo, {
      codigo,
      producto: nombre,
      tipo_insumo: tipo,
      unidad,
      stock_sistema: 0,
      cantidad_lotes: 0,
      lotes: [],
      estado_dato: "VALIDO",
      errores: []
    });
  }

  const producto = productos.get(codigo);

  if (!codigoOriginal) {
    producto.errores.push(
      `Fila ${numeroFila}: código vacío`
    );
  }

  if (!cantidadValida) {
    producto.errores.push(
      `Fila ${numeroFila}: cantidad inválida`
    );
  }

  if (!nombre || !unidad || !tipo) {
    producto.errores.push(
      `Fila ${numeroFila}: información incompleta`
    );
  }

  if (
    producto.producto !== nombre ||
    producto.unidad !== unidad ||
    producto.tipo_insumo !== tipo
  ) {
    producto.errores.push(
      `Fila ${numeroFila}: datos inconsistentes para el código`
    );
  }

  if (!lote) {
    producto.errores.push(
      `Fila ${numeroFila}: lote vacío`
    );
  }

  if (
    lote &&
    producto.lotes.some(x => x.lote === lote)
  ) {
    producto.errores.push(
      `Fila ${numeroFila}: lote repetido`
    );
  }

  if (cantidadValida) {
    producto.stock_sistema += cantidad;
  }

  producto.cantidad_lotes += 1;

  producto.lotes.push({
    lote,
    cantidad: cantidadValida ? cantidad : null,
    fila_origen: numeroFila
  });
}

return Array.from(productos.values()).map(producto => {
  if (producto.errores.length > 0) {
    producto.estado_dato = "REVISAR";
  }

  return {
    json: producto
  };
});

const items = $input.all();

return items.map(item => {
  const fila = item.json;

  const seleccion = String(
    fila["Código del insumo"] ?? ""
  ).trim();

  const codigo = seleccion.split(/\s+[—–-]\s+/)[0].trim();

  const lote = String(
    fila["Código de lote"] ?? ""
  ).trim();

  const cantidadOriginal =
    fila["Cantidad física contada"];

  const cantidad = Number(cantidadOriginal);

  const conteoCompleto = String(
    fila["¿Finalizaste el conteo de todos los lotes de este insumo?"] ?? ""
  ).trim().toLowerCase().startsWith("sí");

  const errores = [];

  if (!codigo) {
    errores.push("Código de insumo vacío");
  }

  if (!lote || lote === "SIN_LOTE") {
    errores.push("Lote no identificado");
  }

  if (
    cantidadOriginal === "" ||
    cantidadOriginal === null ||
    cantidadOriginal === undefined ||
    !Number.isInteger(cantidad) ||
    cantidad < 0
  ) {
    errores.push("Cantidad física inválida");
  }

  if (!conteoCompleto) {
    errores.push("Conteo incompleto");
  }

  return {
    json: {
      fila_origen: fila.row_number,
      fecha_conteo: fila["Marca temporal"],
      responsable: fila["Responsable del conteo"],
      codigo,
      lote,
      cantidad_fisica: Number.isFinite(cantidad)
        ? cantidad
        : null,
      conteo_completo: conteoCompleto,
      observaciones: fila["Observaciones del conteo"],
      estado_preliminar:
        errores.length === 0
          ? "PENDIENTE_CONCILIACION"
          : "REVISAR",
      errores
    }
  };
});

const conteos = $input.all();
const inventario = $("03 - Consolidar stock por código").all();

const mapaInventario = new Map();

for (const item of inventario) {
  mapaInventario.set(
    String(item.json.codigo).trim(),
    item.json
  );
}

return conteos.map(item => {
  const conteo = item.json;

  const producto = mapaInventario.get(
    String(conteo.codigo).trim()
  );

  const errores = [...(conteo.errores ?? [])];

  if (!producto) {
    errores.push("Código inexistente en inventario");
  }

  let loteEncontrado = null;

  if (producto) {
    loteEncontrado = producto.lotes.find(
      l => String(l.lote).trim() ===
           String(conteo.lote).trim()
    );

    if (!loteEncontrado) {
      errores.push("Lote inexistente en inventario");
    }

    if (producto.estado_dato !== "VALIDO") {
      errores.push("Datos del inventario requieren revisión");
    }
  }

  return {
    json: {
      ...conteo,
      producto: producto?.producto ?? "",
      stock_sistema: producto?.stock_sistema ?? null,
      cantidad_lotes_sistema:
        producto?.cantidad_lotes ?? null,
      lote_existe: Boolean(loteEncontrado),
      estado_conciliacion:
        errores.length === 0
          ? "PENDIENTE_VALIDACION_FISICA"
          : "REVISAR",
      errores
    }
  };
});

const filas = $input.all();
const resultado = [];

for (const item of filas) {
  const fila = item.json;

  const vino = String(
    fila["Vino / Varietal"] ?? ""
  ).trim();

  const descripcionInsumos = String(
    fila["Botella - Corcho - Tapa"] ?? ""
  ).trim();

  const fecha = String(
    fila["Fecha"] ?? ""
  ).trim();

  // Excluir totales y subtotales del cronograma.
  // Se revisan varias columnas porque la palabra
  // TOTALES puede aparecer fuera de Vino / Varietal.
  const textoFila = [
    vino,
    fecha,
    descripcionInsumos
  ].join(" ").toUpperCase();

  if (
    /\b(TOTAL|TOTALES|SUBTOTAL|SUBTOTALES)\b/.test(textoFila)
  ) {
    continue;
  }

  const cantidadOriginal = fila["Botellas Previstas"];
  const litrosOriginal = fila["Litros a Llenar"];

  // Ignorar filas completamente vacías.
  if (
    !vino &&
    !descripcionInsumos &&
    (
      cantidadOriginal === "" ||
      cantidadOriginal == null
    )
  ) {
    continue;
  }

  // Evitar interpretar celdas vacías como cero.
  const cantidad =
    cantidadOriginal === "" || cantidadOriginal == null
      ? NaN
      : Number(cantidadOriginal);

  const litros =
    litrosOriginal === "" || litrosOriginal == null
      ? NaN
      : Number(litrosOriginal);

  const errores = [];

  if (!vino) {
    errores.push("Falta vino o varietal");
  }

  if (!descripcionInsumos) {
    errores.push("Falta descripción de insumos");
  }

  if (!fecha) {
    errores.push("Falta fecha de producción");
  }

  if (
    !Number.isInteger(cantidad) ||
    cantidad <= 0
  ) {
    errores.push("Botellas previstas inválidas");
  }

  resultado.push({
    json: {
      fila_origen: fila.row_number,
      fecha_produccion: fecha,
      vino,
      nivel: String(fila["Nivel"] ?? ""),
      descripcion_insumos: descripcionInsumos,
      litros_previstos:
        Number.isFinite(litros) && litros >= 0
          ? litros
          : null,
      botellas_previstas:
        Number.isInteger(cantidad) && cantidad > 0
          ? cantidad
          : null,
      estado:
        errores.length === 0
          ? "PENDIENTE_EQUIVALENCIA"
          : "REVISAR",
      errores
    }
  });
}

return resultado;

const equivalencias = $input.all().map(i => i.json);

const produccion = $("13 - Normalizar programa de producción")
  .all().map(i => i.json);

const inventario = $("03 - Consolidar stock por código")
  .all().map(i => i.json);

const mapaStock = new Map(
  inventario.map(p => [p.codigo, p])
);

const resultados = [];

for (const orden of produccion) {
  for (const eq of equivalencias) {

    const descripcion = String(
      orden.descripcion_insumos ?? ""
    ).toUpperCase();

    const termino = String(
      eq["Descripción cronograma"] ?? ""
    ).toUpperCase();

    if (!termino || !descripcion.includes(termino)) {
      continue;
    }

    const codigo = eq["Código inventario"];
    const producto = mapaStock.get(codigo);

    const estadoEquivalencia = String(
      eq["Estado equivalencia"] ?? ""
    ).toUpperCase();

    const unidades = Number(
      eq["Unidades por botella"]
    );

    const errores = [];

    if (estadoEquivalencia !== "APROBADO") {
      errores.push("Equivalencia pendiente de aprobación");
    }

    if (!producto) {
      errores.push("Código inexistente en inventario");
    }

    if (!Number.isFinite(unidades) || unidades <= 0) {
      errores.push("Factor de consumo inválido");
    }

    if (orden.estado === "REVISAR") {
      errores.push("Producción con datos inválidos");
    }

    const necesidad = (
      Number.isFinite(orden.botellas_previstas) &&
      Number.isFinite(unidades) &&
      unidades > 0
    )
      ? orden.botellas_previstas * unidades
      : null;

    const stock = producto?.stock_sistema ?? null;

    const faltanteTeorico =
      necesidad !== null && stock !== null
        ? Math.max(0, necesidad - stock)
        : null;

    resultados.push({
      json: {
        fecha_produccion: orden.fecha_produccion,
        vino: orden.vino,
        codigo_insumo: codigo,
        descripcion_insumo:
          producto?.producto ?? termino,
        tipo_insumo: eq["Tipo insumo"],
        botellas_previstas: orden.botellas_previstas,
        unidades_por_botella: unidades,
        necesidad,
        stock_sistema: stock,
        faltante_teorico: faltanteTeorico,
        estado:
          errores.length === 0
            ? "PENDIENTE_VALIDACION_STOCK"
            : "REVISAR",
        errores
      }
    });
  }
}

return resultados;

const necesidades = $input.all().map(i => i.json);

const producciones = $("13 - Normalizar programa de producción")
  .all().map(i => i.json);

const filasConEquivalencias = new Set(
  necesidades
    .filter(n => n.fila_produccion != null)
    .map(n => String(n.fila_produccion))
);

// La versión actual del nodo 15 aún no guarda
// fila_produccion, por eso también comprobamos
// fecha y vino.
function tieneCoincidencia(orden) {
  return necesidades.some(n =>
    String(n.fecha_produccion).trim() ===
      String(orden.fecha_produccion).trim() &&
    String(n.vino).trim().toUpperCase() ===
      String(orden.vino).trim().toUpperCase()
  );
}

const resultados = necesidades.map(n => ({
  json: {
    ...n,
    tipo_registro: "NECESIDAD_DE_INSUMO"
  }
}));

for (const orden of producciones) {
  if (!tieneCoincidencia(orden)) {
    resultados.push({
      json: {
        tipo_registro: "PRODUCCION_SIN_EQUIVALENCIA",
        fila_produccion: orden.fila_origen,
        fecha_produccion: orden.fecha_produccion,
        vino: orden.vino,
        descripcion_insumos: orden.descripcion_insumos,
        botellas_previstas: orden.botellas_previstas,
        codigo_insumo: null,
        necesidad: null,
        stock_sistema: null,
        faltante_teorico: null,
        estado: "REVISAR",
        errores: [
          "No se encontraron equivalencias para esta producción"
        ]
      }
    });
  }
}

return resultados;
;

const registros = $input.all().map(i => i.json);

const necesidades = registros.filter(
  r => r.tipo_registro === "NECESIDAD_DE_INSUMO"
);

const sinEquivalencia = registros.filter(
  r => r.tipo_registro === "PRODUCCION_SIN_EQUIVALENCIA"
);

const conRevision = registros.filter(
  r => r.estado === "REVISAR"
);

const informe = {
  fecha_analisis: new Date().toISOString(),
  total_registros: registros.length,
  necesidades_identificadas: necesidades.length,
  producciones_sin_equivalencia: sinEquivalencia.length,
  registros_para_revision: conRevision.length,
  permite_compra_automatica: false,
  necesidades,
  producciones_pendientes: sinEquivalencia,
  reglas: [
    "No aprobar compras automáticamente",
    "No inventar códigos de insumos",
    "No considerar validado el stock del sistema",
    "Solicitar revisión cuando falten equivalencias",
    "No confirmar disponibilidad sin conteo físico validado"
  ]
};

return [{
  json: {
    informe,
    informe_texto: JSON.stringify(informe, null, 2)
  }
}];

const respuestas = $input.all();

const informe = $("17 - Preparar informe para agente IA")
  .first().json.informe;

return respuestas.map((item, index) => {

  const textoIA = String(item.json.output ?? "").trim();

  const bloqueos = [];

  if (informe.permite_compra_automatica !== true) {
    bloqueos.push("Compra automática deshabilitada");
  }

  if (informe.registros_para_revision > 0) {
    bloqueos.push("Existen registros pendientes de revisión");
  }

  if (informe.producciones_sin_equivalencia > 0) {
    bloqueos.push("Existen producciones sin equivalencia");
  }

  if (!textoIA) {
    bloqueos.push("Respuesta de IA vacía");
  }

  // La IA redacta recomendaciones, pero el estado
  // seguro lo determinan las reglas del workflow.
  const accion = bloqueos.length > 0
    ? "REVISAR_DATOS"
    : "PENDIENTE_EVALUACION";

  const idAnalisis =
    "ANALISIS-" +
    String(informe.fecha_analisis ?? "").replace(
      /[^0-9]/g, ""
    ) +
    "-" + (index + 1);

  return {
    json: {
      "ID análisis": idAnalisis,
      "Fecha análisis": informe.fecha_analisis,
      "Acción recomendada": accion,
      "Registros analizados": informe.total_registros,
      "Necesidades identificadas":
        informe.necesidades_identificadas,
      "Producciones pendientes":
        informe.producciones_sin_equivalencia,
      "Resumen IA": textoIA || "Sin respuesta del agente",
      "Estado validación":
        bloqueos.length > 0
          ? "REQUIERE_REVISION"
          : "PENDIENTE_EVALUACION",
      "Aprobación humana": "NO",
      "Motivos bloqueo": bloqueos
    }
  };
});
